// #region 🔖StatusBadge
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖statusbadge](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/StatusBadge)

/**
 * Displays a colored badge for compliance status.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖statusbadge🛠️statusbadge](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/StatusBadge/d/i/StatusBadge)
 *
 * MUST render green for compliant, red for violated, gray for unknown.
 **/
function StatusBadge({ status }: { status?: string }) {
  const colors: Record<string, string> = {
    compliant: "bg-compliant/15 text-compliant border-compliant/30",
    violated: "bg-violated/15 text-violated border-violated/30",
    unknown: "bg-unknown/15 text-unknown border-unknown/30",
  };
  const s = status ?? "unknown";
  return (
    <span className={`inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-xs font-medium ${colors[s] ?? colors.unknown}`}>
      {s === "compliant" && <IconCheck className="w-3 h-3" />}
      {s === "violated" && <IconX className="w-3 h-3" />}
      {s}
    </span>
  );
}

// #endregion 🔖StatusBadge

// #region 🔖Card
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖card](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/Card)

/**
 * A card container for dashboard sections.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖card🛠️card](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/Card/d/i/Card)
 *
 * MUST render a bordered container with optional title.
 **/
function Card({ title, children, className = "", action }: { title?: string; children: React.ReactNode; className?: string; action?: React.ReactNode }) {
  return (
    <div className={`rounded-lg border border-border bg-surface ${className}`}>
      {(title || action) && (
        <div className="flex items-center justify-between border-b border-border px-4 py-3">
          {title && <h3 className="text-sm font-semibold text-text">{title}</h3>}
          {action}
        </div>
      )}
      <div className="p-4">{children}</div>
    </div>
  );
}

// #endregion 🔖Card

// #region 🔖StatCard
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖statcard](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/StatCard)

/**
 * A metric card for the dashboard overview.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖statcard🛠️statcard](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/StatCard/d/i/StatCard)
 *
 * MUST display a label and a large value.
 **/
function StatCard({ label, value, sublabel }: { label: string; value: string | number; sublabel?: string }) {
  return (
    <div className="rounded-lg border border-border bg-surface p-4">
      <div className="text-xs font-medium text-text-tertiary uppercase tracking-wider">{label}</div>
      <div className="mt-1 text-2xl font-bold text-text">{value}</div>
      {sublabel && <div className="mt-0.5 text-xs text-text-secondary">{sublabel}</div>}
    </div>
  );
}

// #endregion 🔖StatCard

// #region 🔖Button
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖button](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/Button)

/**
 * A styled button with variant support.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖button🛠️button](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/Button/d/i/Button)
 *
 * MUST support primary, secondary, and danger variants.
 **/
function Button({
  children,
  onClick,
  variant = "secondary",
  disabled = false,
  loading = false,
  className = "",
}: {
  children: React.ReactNode;
  onClick?: () => void;
  variant?: "primary" | "secondary" | "danger";
  disabled?: boolean;
  loading?: boolean;
  className?: string;
}) {
  const variants: Record<string, string> = {
    primary: "bg-coda-600 text-white hover:bg-coda-700 disabled:bg-coda-400",
    secondary: "bg-surface border border-border text-text hover:bg-surface-hover disabled:opacity-50",
    danger: "bg-violated/10 text-violated border border-violated/30 hover:bg-violated/20 disabled:opacity-50",
  };
  return (
    <button
      onClick={onClick}
      disabled={disabled || loading}
      className={`inline-flex items-center gap-2 rounded-md px-3 py-1.5 text-sm font-medium transition-colors cursor-pointer disabled:cursor-not-allowed ${variants[variant]} ${className}`}
    >
      {loading && (
        <svg className="w-3.5 h-3.5 animate-spin" viewBox="0 0 24 24" fill="none">
          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
        </svg>
      )}
      {children}
    </button>
  );
}

// #endregion 🔖Button

// #endregion 🔖Button

// #region 🔖Spinner
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖spinner](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/Spinner)

/**
