// #endregion 🔖EmptyState

// #region 🔖Collapsible
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖collapsible](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/Collapsible)

/**
 * A collapsible section with toggle.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖collapsible🛠️collapsible](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/Collapsible/d/i/Collapsible)
 *
 * MUST toggle visibility on header click.
 **/
function Collapsible({ title, children, defaultOpen = false, badge }: { title: string; children: React.ReactNode; defaultOpen?: boolean; badge?: React.ReactNode }) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div className="border border-border rounded-md overflow-hidden">
      <button onClick={() => setOpen(!open)} className="flex w-full items-center gap-2 px-3 py-2 text-sm font-medium text-text hover:bg-surface-hover transition-colors cursor-pointer">
        {open ? <IconChevronDown className="w-3.5 h-3.5 text-text-tertiary" /> : <IconChevronRight className="w-3.5 h-3.5 text-text-tertiary" />}
        <span className="flex-1 text-left">{title}</span>
        {badge}
      </button>
      {open && <div className="border-t border-border px-3 py-2">{children}</div>}
    </div>
  );
}

// #endregion 🔖Collapsible

// #region 🔖JsonViewer
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖jsonviewer](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/JsonViewer)

/**
 * A formatted JSON viewer for translation data.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖jsonviewer🛠️jsonviewer](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/JsonViewer/d/i/JsonViewer)
 *
 * MUST display formatted JSON in a code block.
 **/
function JsonViewer({ data }: { data: unknown }) {
  const formatted = useMemo(() => {
    try {
      return JSON.stringify(data, null, 2);
