// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖ontologytree](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/OntologyTree)
// Tree viewer for visualizing OWL class expression structure (schema-level, no instances).
// OntologyTree MUST render a collapsible tree of the class expression without truth values.

/**
 * Node kind in an ontology class expression tree.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖ontologytree✂️ontologynodekind](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/OntologyTree/d/f/OntologyNodeKind)
 *
 * Enumerates all OWL class expression constructs.
 **/
type OntologyNodeKind =
  | "Class"
  | "And"
  | "Or"
  | "Not"
  | "SomeValuesFrom"
  | "AllValuesFrom"
  | "ExactCardinality"
  | "MinCardinality"
  | "MaxCardinality"
  | "DataSomeValuesFrom"
  | "DataAllValuesFrom"
  | "DataHasValue"
  | "DatatypeRestriction";

/**
 * A node in the ontology class expression tree (schema only, no instances).
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖ontologytree✂️ontologytreenode](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/OntologyTree/d/f/OntologyTreeNode)
 *
 * MUST have id, kind, label, and children.
 **/
interface OntologyTreeNode {
  id: string;
  kind: OntologyNodeKind;
  label: string;
  fragment?: string;
  property?: string;
  className?: string;
  cardinality?: number;
  datatype?: string;
  restriction?: string;
  children: OntologyTreeNode[];
}

/**
 * Returns the icon label for an ontology node kind.
 **/
function ontologyNodeIcon(kind: OntologyNodeKind): string {
  switch (kind) {
    case "Class": return "C";
    case "And": return "∧";
    case "Or": return "∨";
    case "Not": return "¬";
    case "SomeValuesFrom": return "∃";
    case "AllValuesFrom": return "∀";
    case "ExactCardinality": return "=n";
    case "MinCardinality": return "≥n";
    case "MaxCardinality": return "≤n";
    case "DataSomeValuesFrom": return "∃d";
    case "DataAllValuesFrom": return "∀d";
    case "DataHasValue": return "v";
    case "DatatypeRestriction": return "D";
    default: return "?";
  }
}

/**
