// #region 🔖Hooks
// [🔬coda🖱️desktop💻renderer🔖renderer🔖hooks](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Hooks)
// Custom React hooks for fetching coda MCP data.
// Hooks MUST handle loading, error, and data states.

/**
 * Fetches a coda MCP resource and returns parsed data.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖hooks🛠️usecodaResource](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Hooks/d/i/useCodaResource)
 *
 * MUST refetch when uri or refreshKey changes.
 **/
function useCodaResource<T>(uri: string, refreshKey: number = 0): { data: T | null; loading: boolean; error: string | null; refresh: () => void } {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [localRefresh, setLocalRefresh] = useState(0);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    window.coda
      .fetch(uri)
      .then((response) => {
        if (cancelled) return;
        const parsed = parseMcpResource<T>(response);
        if (parsed !== null) {
          const obj = parsed as Record<string, unknown>;
          if (obj && typeof obj === "object" && "error" in obj) {
            setError(obj.error as string);
            setData(null);
          } else {
            setData(parsed);
          }
        } else if (response.error) {
          setError(response.error.message);
        } else {
          setData(null);
        }
        setLoading(false);
      })
      .catch((err) => {
        if (cancelled) return;
        setError(err?.message ?? "Failed to fetch");
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [uri, refreshKey, localRefresh]);

  const refresh = useCallback(() => setLocalRefresh((n) => n + 1), []);
  return { data, loading, error, refresh };
}

