/* SPDX-License-Identifier: AGPL-3.0-only */
@import "tailwindcss";
@import "./theme.css";
@import "golden-layout/dist/css/goldenlayout-base.css";
@import "golden-layout/dist/css/themes/goldenlayout-dark-theme.css";
@plugin "@tailwindcss/typography";

#navbar {
  position: relative !important;
  z-index: var(--z-base) !important;
  pointer-events: auto !important;
}

#navbar button,
#navbar [role="button"],
#navbar a,
#navbar [role="link"],
#navbar input,
#navbar select,
#navbar textarea {
  pointer-events: auto !important;
  -webkit-app-region: no-drag !important;
}

#navbar {
  -webkit-app-region: drag !important;
}

.lm_goldenlayout {
  background-color: var(--base) !important;
  color: var(--foreground) !important;
  z-index: var(--z-base) !important;
  position: relative !important;
  pointer-events: auto !important;
  overflow: hidden !important;
}

.lm_goldenlayout * {
  pointer-events: auto !important;
}

.lm_root {
  z-index: var(--z-base) !important;
  position: relative !important;
  overflow: hidden !important;
}

.lm_item {
  z-index: var(--z-base) !important;
  position: relative !important;
  box-sizing: border-box !important;
}

.lm_header,
.lm_tabs,
.lm_controls {
  z-index: var(--z-panel) !important;
}

.lm_header {
  display: flex !important;
  visibility: visible !important;
  height: 20px !important;
  min-height: 20px !important;
  max-height: 20px !important;
  opacity: 1 !important;
  z-index: var(--z-panel) !important;
  position: relative !important;
  background-color: transparent !important;
  border-bottom: 1px solid var(--border-color) !important;
}

.lm_tabs {
  display: flex !important;
  visibility: visible !important;
  opacity: 1 !important;
  flex: 1 !important;
  background-color: transparent !important;
}

.lm_tab {
  display: flex !important;
  visibility: visible !important;
  opacity: 1 !important;
  background-color: var(--window) !important;
  color: var(--foreground) !important;
  padding: 2px 8px !important;
  cursor: var(--cursor-pointer) !important;
  border-top: 1px solid var(--border-color) !important;
  border-right: 1px solid var(--border-color) !important;
  user-select: none !important;
  -webkit-user-select: none !important;
  margin-bottom: -1px !important;
  padding-bottom: 3px !important;
}

.lm_tab:hover {
  background-color: var(--hover-window) !important;
}

.lm_tab.lm_active {
  background-color: var(--window) !important;
  color: var(--foreground) !important;
}

.lm_title {
  opacity: 1 !important;
  visibility: visible !important;
  color: var(--foreground) !important;
  font-size: var(--text-xs) !important;
  line-height: var(--text-xs--line-height) !important;
}

.lm_controls {
  display: flex !important;
  visibility: visible !important;
  opacity: 1 !important;
  flex-shrink: 0 !important;
  background-color: transparent !important;
}

.lm_close_tab {
  display: none !important;
  visibility: hidden !important;
}

.lm_popout,
.lm_maximise,
.lm_close {
  display: none !important;
  visibility: hidden !important;
}

.lm_popout:hover,
.lm_maximise:hover,
.lm_close:hover {
  background-color: transparent !important;
}

.lm_popout::before {
  content: "□" !important;
  display: block !important;
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  transform: translate(-50%, -50%) !important;
  color: var(--foreground) !important;
  font-size: 10px !important;
  line-height: 1 !important;
}

.lm_maximise::before {
  content: "■" !important;
  display: block !important;
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  transform: translate(-50%, -50%) !important;
  color: var(--foreground) !important;
  font-size: 8px !important;
  line-height: 1 !important;
}

.lm_close::before {
  content: "×" !important;
  display: block !important;
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  transform: translate(-50%, -50%) !important;
  color: var(--foreground) !important;
  font-size: 14px !important;
  line-height: 1 !important;
  font-weight: bold !important;
}

.lm_item.lm_stack {
  border: none !important;
  position: relative !important;
  background-color: transparent !important;
}

.lm_item.lm_stack::after {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  box-shadow:
    inset 1px 0 0 0 var(--border-color),
    inset -1px 0 0 0 var(--border-color),
    inset 0 -1px 0 0 var(--border-color) !important;
  z-index: var(--z-panel) !important;
  pointer-events: none !important;
}

.lm_item.lm_component {
  border: none !important;
  box-shadow: none !important;
  background-color: var(--window) !important;
}

.lm_content {
  border: none !important;
  background-color: var(--window) !important;
}

.lm_items {
  border: none !important;
}

.lm_splitter {
  background-color: var(--base) !important;
}
.lm_splitter.lm_splitter_vertical {
  width: var(--spacing-single) !important;
  min-width: var(--spacing-single) !important;
  cursor: var(--cursor-ew-resize) !important;
}
.lm_splitter.lm_splitter_horizontal {
  height: var(--spacing-single) !important;
  min-height: var(--spacing-single) !important;
  cursor: var(--cursor-ns-resize) !important;
}

.lm_splitter:hover {
  background-color: var(--border-element-color) !important;
}

