    [style*="cursor:not-allowed"] {
      cursor: var(--cursor-not-allowed) !important;
    }

    [class*="cursor-not-allowed"]:is(:disabled, [aria-disabled="true"], [data-disabled="true"]) {
      cursor: var(--cursor-not-allowed) !important;
    }

    .cursor-help,
    [style*="cursor: help"],
