.fullscreen #navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  transform: translateY(-100%);
  transition: transform 0.2s ease-in-out;
  z-index: var(--z-modal);
}

.fullscreen #navbar:hover,
.fullscreen #navbar:focus-within {
  transform: translateY(0);
}

.fullscreen #footer {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  transform: translateY(100%);
  transition: transform 0.2s ease-in-out;
  z-index: var(--z-modal);
}

.fullscreen #footer:hover,
.fullscreen #footer:focus-within {
  transform: translateY(0);
}

.fullscreen:has(#navbar:hover) #navbar,
.fullscreen:has(#footer:hover) #footer {
  transform: translateY(0);
}

@media (pointer: coarse) {
  .fullscreen #navbar,
  .fullscreen #footer {
    transition: none;
  }
}

